import { useQuery } from "@tanstack/react-query";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { BookOpen, Lock, CheckCircle, ArrowRight } from "lucide-react";
import { Link } from "wouter";
import type { Lesson, UserLessonProgress } from "@shared/schema";

const skillColors: Record<string, string> = {
  reading: "bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300",
  writing: "bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-300",
  listening: "bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300",
  speaking: "bg-violet-100 dark:bg-violet-900/30 text-violet-700 dark:text-violet-300",
  general: "bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300",
};

export default function LessonsPage() {
  const { data: lessons, isLoading } = useQuery<Lesson[]>({
    queryKey: ["/api/lessons"],
  });

  const { data: progress } = useQuery<UserLessonProgress[]>({
    queryKey: ["/api/user/progress"],
  });

  const progressMap = new Map(progress?.map((p) => [p.lessonId, p]) || []);

  const levels = [1, 2, 3, 4, 5];

  if (isLoading) {
    return (
      <div className="p-6 max-w-5xl mx-auto space-y-4">
        <Skeleton className="h-10 w-64" />
        {[1, 2, 3, 4].map((i) => <Skeleton key={i} className="h-24" />)}
      </div>
    );
  }

  return (
    <div className="p-6 max-w-5xl mx-auto">
      <div className="mb-8">
        <h1 className="text-2xl font-bold" data-testid="text-lessons-title">Lessons</h1>
        <p className="text-muted-foreground mt-1">Master Arabic step by step</p>
        <p className="text-lg mt-1" dir="rtl" style={{ fontFamily: "'Amiri', serif" }}>
          الدروس التعليمية
        </p>
      </div>

      <Tabs defaultValue="1">
        <TabsList className="mb-6">
          {levels.map((lvl) => {
            const count = lessons?.filter((l) => l.level === lvl).length || 0;
            return (
              <TabsTrigger key={lvl} value={String(lvl)} data-testid={`tab-level-${lvl}`}>
                Level {lvl} {count > 0 && <Badge variant="secondary" className="ml-1.5 text-xs">{count}</Badge>}
              </TabsTrigger>
            );
          })}
        </TabsList>

        {levels.map((lvl) => (
          <TabsContent key={lvl} value={String(lvl)} className="space-y-3">
            {lessons?.filter((l) => l.level === lvl).sort((a, b) => a.orderIndex - b.orderIndex).map((lesson) => {
              const prog = progressMap.get(lesson.id);
              const completed = prog?.completed;

              return (
                <Link key={lesson.id} href={`/lessons/${lesson.id}`}>
                  <Card className="hover-elevate active-elevate-2 cursor-pointer" data-testid={`card-lesson-${lesson.id}`}>
                    <CardContent className="p-5">
                      <div className="flex items-center gap-4">
                        <div className="w-14 h-14 rounded-md bg-primary/10 flex items-center justify-center shrink-0">
                          {completed ? (
                            <CheckCircle className="w-6 h-6 text-emerald-500" />
                          ) : (
                            <span className="text-2xl" style={{ fontFamily: "'Amiri', serif" }}>
                              {lesson.titleAr?.charAt(0) || "ع"}
                            </span>
                          )}
                        </div>
                        <div className="flex-1 min-w-0">
                          <div className="flex flex-wrap items-center gap-2">
                            <h3 className="font-semibold">{lesson.title}</h3>
                            {completed && <Badge variant="outline" className="text-xs text-emerald-600 dark:text-emerald-400">Completed</Badge>}
                          </div>
                          <p className="text-sm text-muted-foreground mt-0.5" dir="rtl" style={{ fontFamily: "'Amiri', serif" }}>
                            {lesson.titleAr}
                          </p>
                          <p className="text-xs text-muted-foreground mt-1 line-clamp-1">{lesson.description}</p>
                          <div className="flex flex-wrap items-center gap-2 mt-2">
                            <Badge variant="secondary" className={`text-xs ${skillColors[lesson.skillFocus] || ""}`}>
                              {lesson.skillFocus}
                            </Badge>
                            <Badge variant="outline" className="text-xs">{lesson.xpReward} XP</Badge>
                            <Badge variant="outline" className="text-xs">{lesson.category}</Badge>
                          </div>
                        </div>
                        <Button size="icon" variant="ghost" className="shrink-0" data-testid={`button-start-lesson-${lesson.id}`}>
                          <ArrowRight className="w-4 h-4" />
                        </Button>
                      </div>
                    </CardContent>
                  </Card>
                </Link>
              );
            })}
            {(!lessons || lessons.filter((l) => l.level === lvl).length === 0) && (
              <div className="text-center py-16 text-muted-foreground">
                <Lock className="w-12 h-12 mx-auto mb-4 opacity-30" />
                <p className="font-medium">No lessons available at this level yet</p>
                <p className="text-sm mt-1">Check back soon for new content</p>
              </div>
            )}
          </TabsContent>
        ))}
      </Tabs>
    </div>
  );
}

