          { arabic: "فَتَحَ", transliteration: "fataḥa", meaning: "he opened" },
        ],
      },
      {
        name: "Damma", nameAr: "ضَمَّة", symbol: "ـُ", sound: "Short 'u' (as in 'put')", ipa: "/u/",
